</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include<algorithm>
#include<iostream>
#include<cstring>
#include<cstdio>
using namespace std;
const int MOD = 1000000007;
const int maxn = 8;
const int SZ = 1048576 + 5;

inline int inc(int a, int b) { return (a + b >= MOD) ? (a + b - MOD) : (a + b); }
inline int dec(int a, int b) { return (a >= b) ? (a - b) : (a + MOD - b); }
inline int mul(int a, int b) { return 1LL * a * b % MOD; }
inline void updata(int &x, int y) { x = inc(x,y); }

int power(int x, int k) {
    int res = 1;
    while(k) { if(k&1) res = mul(res,x); x = mul(x,x); k >>= 1; }
    return res;
}

int n, a[maxn][maxn], inv100, g[maxn][maxn], p[SZ], all, Ans;
int trip[20][3];
int comp[20];
int cnt;

inline bool check(int x, int y, int z) {
    int pos[4], lis[4];
    lis[1]=x; lis[2]=y; lis[3]=z;
    for(int i=1;i<=3;i++) pos[i]=i;
    do {
        bool ok = true;
        for(int i=1;i<=3;i++) if(!g[pos[i]][lis[i]]) { ok=false; break; }
        if(ok) return true;
    } while(next_permutation(pos+1,pos+4));
    return false;
}

void dfs1(int now, int x, int y) {
    if(!now) return;
    if(x == 4) {
        int sta = 0;
        for(int t=0; t<cnt; t++) {
            int i = trip[t][0], j = trip[t][1], k = trip[t][2];
            if(check(i,j,k)) {
                sta |= comp[t];
            }
        }
        updata(p[sta], now);
        return;
    }
    g[x][y] = 1; int nxt = mul(now, a[x][y]);
    if(y==6) dfs1(nxt, x+1, 1); else dfs1(nxt, x, y+1);
    g[x][y] = 0; nxt = mul(now, dec(1, a[x][y]));
    if(y==6) dfs1(nxt, x+1, 1); else dfs1(nxt, x, y+1);
}

void dfs2(int now, int x, int y) {
    if(!now) return;
    if(x == 7) {
        int sta = 0;
        for(int t=0; t<cnt; t++) {
            int i = trip[t][0], j = trip[t][1], k = trip[t][2];
            if(check(i,j,k)) {
                sta |= (1<<t);
            }
        }
        updata(Ans, mul(now, p[all ^ sta]));
        return;
    }
    g[x-3][y] = 1; int nxt = mul(now, a[x][y]);
    if(y==6) dfs2(nxt, x+1, 1); else dfs2(nxt, x, y+1);
    g[x-3][y] = 0; nxt = mul(now, dec(1, a[x][y]));
    if(y==6) dfs2(nxt, x+1, 1); else dfs2(nxt, x, y+1);
}

int main() {
    scanf("%d", &n);
    inv100 = power(100, MOD-2);
    for(int i=1;i<=n;i++) for(int j=1;j<=n;j++) { scanf("%d", &a[i][j]); a[i][j] = mul(a[i][j], inv100); }
    for(int i=n+1;i<=6;i++) a[i][i] = 1;

    cnt = 0;
    int tripIndex[7][7][7] = {0};
    for(int i=1;i<=6;i++) for(int j=i+1;j<=6;j++) for(int k=j+1;k<=6;k++) {
        trip[cnt][0]=i; trip[cnt][1]=j; trip[cnt][2]=k;
        tripIndex[i][j][k] = cnt;
        cnt++;
    }
    for(int t=0; t<cnt; t++) {
        int i=trip[t][0], j=trip[t][1], k=trip[t][2];
        int found[7] = {0};
        found[i]=found[j]=found[k]=1;
        int compTri[3], cc=0;
        for(int a=1;a<=6;a++) if(!found[a]) compTri[cc++]=a;
        comp[t] = 1 << tripIndex[compTri[0]][compTri[1]][compTri[2]];
    }

    all = (1 << cnt) - 1;
    dfs1(1, 1, 1);
    for(int j=0;j<cnt;j++) {
        for(int i=0;i<(1<<cnt);i++) {
            if(i & (1<<j)) updata(p[i], p[i ^ (1<<j)]);
        }
    }
    Ans = 0;
    dfs2(1, 4, 1);
    Ans = dec(1, Ans);
    printf("%d\n", Ans);
    return 0;
}
